WITH session_totals AS (SELECT session_id, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events WHERE page NOT IN ('/search', '/product', '/checkout') GROUP BY session_id) SELECT s.id, s.country, st.duration_sec_range, st.stddev_duration_sec FROM sessions s JOIN session_totals st ON s.id = st.session_id WHERE st.duration_sec_range >= 55 ORDER BY st.duration_sec_range
